import copy
import json


def _canonical_json(value):
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def evaluate(request, evidence, policy):
    required = policy.get("required_conditions", [])
    request_conditions = request.get("conditions", {})
    missing = sorted(name for name in required if name not in request_conditions)
    if missing:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": missing,
        }

    eligible = []
    require_verified = policy.get("require_verified", False)
    for record in evidence:
        if record.get("claim") != request.get("claim"):
            continue
        if record.get("withdrawn") is True:
            continue
        if require_verified and record.get("verified") is not True:
            continue
        conditions = record.get("conditions", {})
        if any(
            name not in conditions
            or _canonical_json(conditions[name])
            != _canonical_json(request_conditions[name])
            for name in required
        ):
            continue
        eligible.append(record)

    superseded = set()
    for record in eligible:
        supersedes = record.get("supersedes", [])
        if isinstance(supersedes, str):
            supersedes = [supersedes]
        if isinstance(supersedes, list):
            superseded.update(
                source
                for source in supersedes
                if source != record.get("source")
            )
    eligible = [record for record in eligible if record.get("source") not in superseded]

    if not eligible:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": ["no matching evidence"],
        }

    sources = sorted(record["source"] for record in eligible)
    canonical_values = {_canonical_json(record.get("value")) for record in eligible}
    if len(canonical_values) != 1:
        return {
            "status": "conflict",
            "value": None,
            "sources": sources,
            "unknowns": ["source disagreement"],
        }

    value = copy.deepcopy(eligible[0].get("value"))
    status = "unsupported" if value is False else "supported"
    return {
        "status": status,
        "value": value,
        "sources": sources,
        "unknowns": [],
    }

